import json, re

def grader_rule(output, gts):
    # fixed rule: last '#### <number>' equals gold numerically
    matches = re.findall(r'####\s*(-?[0-9][0-9.,]*)', output)
    if not matches:
        return False
    last = matches[-1].replace(',','').replace('\$','').strip()
    try:
        return float(last) == float(gts.replace(',',''))
    except:
        return last == gts.replace(',','')

for stepfile in ['results/run100/val_generations/0.jsonl','results/run100/val_generations/50.jsonl','results/run100/val_generations/100.jsonl']:
    mism = 0; total=0; grader_correct=0; stored_correct=0
    examples=[]
    with open(stepfile) as f:
        for line in f:
            d=json.loads(line)
            total+=1
            g = grader_rule(d['output'], d['gts'])
            s = (d.get('score',0) == 1)
            grader_correct += g
            stored_correct += s
            if g != s:
                mism += 1
                if len(examples)<5:
                    examples.append((d['gts'], d['output'][-120:], d.get('score')))
    print(stepfile, 'total', total, 'grader_correct', grader_correct, 'stored_correct', stored_correct, 'mismatch', mism)
    for e in examples:
        print('   gts=',e[0],'stored_score=',e[2],'tail=',repr(e[1]))
    print()
"

