cd /workspace && cat > /tmp/verify_train_rollout_scores.py << 'EOF'
import json, re

def extract(solution_str, method='strict'):
    if len(solution_str) > 300:
        solution_str = solution_str[-300:]
    if method == 'strict':
        solutions = re.findall(r"#### (\-?[0-9\.\,]+)", solution_str)
        if len(solutions) == 0:
            return None
        return solutions[-1].replace(',', '').replace('$', '')

for fname in ['1','50','100']:
    n = 0; mm = 0; correct = 0
    lens = []
    per_group = {}
    # need uid for groups; rollout jsonl may not have uid. use input hash
    with open(f'results/run100/rollouts/{fname}.jsonl') as f:
        for line in f:
            rec = json.loads(line)
            n += 1
            stored = rec['score']
            out = rec['output']
            gt = rec['gts']
            a = extract(out)
            my = 0.0 if a is None else (1.0 if a == gt else 0.0)
            if my != stored:
                mm += 1
            if my == 1.0:
                correct += 1
            lens.append(len(out))
    print(f'rollout {fname}: n={n}, correct={correct}, rate={correct/n:.4f}, mismatches={mm}')
EOF
